class TemporalLNS

// Count surviving flights whose launch loses too many lower residents.
// This is a repair-cost proxy, not a lower bound on required extra moves.
int brokenSupportJumps(const vector<int>& ids) const {
    array<bool,MV> removed{};
    for(int id:ids)removed[id]=true;
    int broken=0;
    for(const auto& use:supportUses) {
        int lost=0;
        for(int j=0;j<use.lower.n;j++)lost+=removed[use.lower.id[j]];
        if(lost<=use.slack)continue;
        const auto& flight=flights[use.time];
        for(int j=0;j<flight.n;j++)if(!removed[flight.id[j]]){++broken;break;}
    }
    return broken;
}
int growDependency(Removal& cand) const {

        LOCAL_NOTE(const double repair_priority_start=clk.elapsed();int repair_priority_penalized=0;)
        for(auto& cand:candidates) {
            int saved=savedBy(cand.ids,int(cand.ids.size()),0);
            cand.broken_support_jumps=brokenSupportJumps(cand.ids);
            // Retain one draw at the parent's original position, even when
            // the resulting priority is negative. No candidate is removed.
            const double noise=0.90+0.20*rng.unit();
            cand.priority=(saved-cand.broken_support_jumps+0.25)/divisor[cand.ids.size()]*noise;
#ifdef AHC072_REPAIR_AUDIT
            cand.original_priority=(saved+0.25)/divisor[cand.ids.size()]*noise;
#endif
            LOCAL_NOTE(repair_priority_penalized+=cand.broken_support_jumps>0;)
        }
        LOCAL_NOTE(trace.count_by("lns_repair_priority_evaluated",int(candidates.size()));
                   trace.count_by("lns_repair_priority_penalized",repair_priority_penalized);
                   trace.add_time_ms("lns_repair_priority",(clk.elapsed()-repair_priority_start)*1000.0);)
